$_MODULE['<{vatnumber}prestashop>vatnumber_c2c74b135cab679a815e04b2a9d5eec0'] = 'Les numeros confirmes sont servis depuis le cache local pendant 30 jours et reverifies tous les 180 jours, car les immatriculations a la TVA peuvent expirer.';
