$_MODULE['<{vatnumber}prestashop>vatnumber_f557912d9b773f3b62ab61d7239e69ec'] = 'Les clients de votre propre pays paient toujours la TVA. Les espaces et les points dans le numero ne posent aucun probleme, les numeros grecs saisis avec le prefixe GR sont traites comme EL, et les entreprises d\'Irlande du Nord (numero XI, adresse GB) sont prises en charge.';
$_MODULE['<{vatnumber}prestashop>vatnumber_d17a37903c2ff7ec71c5bae45d1e5a22'] = 'Date au format AAAA-MM-JJ, ou vide pour tout verifier. Les numeros en file d\'attente de clients sans changement d\'adresse ni commande depuis cette date sont retires de la file de verification. Utile apres la mise a jour d\'une boutique avec des annees d\'anciennes adresses. Les numeros retires sont simplement reverifies en direct si un tel client revient un jour.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b9f5c797ebbf55adccdd8539a65a0241'] = 'Desactive';
$_MODULE['<{vatnumber}prestashop>vatnumber_ac2f6a9cfa32070c4499f4879221058e'] = 'Desactive (par defaut) : les clients obtiennent l\'exoneration de TVA immediatement, meme pendant que leur numero attend encore la verification. Active : les clients continuent de payer la TVA jusqu\'a ce que VIES ait confirme leur numero. Active est plus sur pour vous, desactive est plus agreable pour le client. Pertinent uniquement lorsque la verification automatique est activee. Les numeros rejetes par VIES n\'obtiennent jamais l\'exoneration, dans aucun des deux modes.';
$_MODULE['<{vatnumber}prestashop>vatnumber_c3611ab7e05da6ec6a6d66098df71627'] = 'Chaque execution verifie %d numeros. Pour vider plus vite une grande file, ajoutez &limit=%d a l\'URL (le maximum par execution).';
$_MODULE['<{vatnumber}prestashop>vatnumber_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Active';
