$_MODULE['<{vatnumber}prestashop>vatnumber_c547522aa7d85ddc28764bd5ea6ad860'] = 'Pendant 5 minutes, aucune nouvelle requete VIES n\'est envoyee, afin que l\'IP de votre serveur ne soit pas limitee.';
